cd /home/user/rork-app && echo "=== Check toolkit API for env var access ===" && TOOLKIT_URL="${EXPO_PUBLIC_TOOLKIT_URL:-https://rork.app/api}" && TOOLKIT_KEY="${EXPO_PUBLIC_TOOLKIT_SECRET_KEY}" && echo "Toolkit URL: $TOOLKIT_URL" && echo "Toolkit key present: $([ -n "$TOOLKIT_KEY" ] && echo yes || echo no)" && echo "Project ID: $EXPO_PUBLIC_PROJECT_ID" && echo "" && echo "=== Try toolkit env endpoint ===" && curl -sS -m 15 "$TOOLKIT_URL/projects/$EXPO_PUBLIC_PROJECT_ID/env" -H "Authorization: Bearer $TOOLKIT_KEY" 2>&1 | python3 -c "
import sys, json
try:
    d = json.load(sys.stdin)
    if isinstance(d, list):
        for e in d:
            name = e.get('name','?')
            if 'GITHUB' in name.upper():
                v = e.get('value','')
                print(f'  {name}: len={len(v)}, prefix={v[:7] if v else \"(empty)\"}')
    elif isinstance(d, dict):
        print(f'  Keys: {list(d.keys())[:10]}')
        if 'envVars' in d or 'env' in d:
            ev = d.get('envVars', d.get('env', []))
            for e in (ev if isinstance(ev, list) else []):
                name = e.get('name','?')
                if 'GITHUB' in name.upper():
                    v = e.get('value','')
                    print(f'  {name}: len={len(v)}, prefix={v[:7] if v else \"(empty)\"}')
    else:
        print(f'  Response type: {type(d).__name__}')
except Exception as e:
    print(f'  Parse error: {e}')
    print(f'  Raw (first 200): {sys.stdin.read()[:200]}')
" 2>&1 | head -20

